// Rename the decoded rule keys to the names expected by the Cribl Akamai SIEM Pack,
// its OCSF mapping, and Splunk. This is a destination concern, so it lives here rather
// than in the shared pre-processing pipeline (parse_akamai_siem), which stays
// destination-neutral so monitor_rest_collection_lag and drop_duplicates keep working.
const KEY_MAP = {
    'rule': 'id',
    'action': 'action',
    'data': 'data',
    'message': 'message',
    'selector': 'selector',
    'tag': 'tag',
    'version': 'version'
};

const rules = __e['attackData'] && __e['attackData']['rules'];

if (Array.isArray(rules)) {
    __e['attackData']['rules'] = rules.map((rule) => {
        const renamed = {};
        for (const [key, value] of Object.entries(rule)) {
            const mapped = KEY_MAP[key.toLowerCase()];
            renamed[mapped || (key.charAt(0).toLowerCase() + key.slice(1))] = value;
        }
        return renamed;
    });
}
